                case TouchPhase.Ended:
                    OnFingerUp(touch.fingerId, pos);
                    break;
                case TouchPhase.Canceled:
                    OnTouchCancelled(touch.fingerId);
                    break;
            }
        }
    }
}

Gesture Recognition:
class GestureRecognizer {
    constructor() {
        this.touches = new Map();
        this.tapThreshold = 300;  // ms
        this.tapDistance = 10;     // px
        this.swipeVelocity = 500;  // px/s
    }

    onTouchBegan(id, pos, time) {
        this.touches.set(id, { start: pos, time, moved: false });
    }

    onTouchMoved(id, pos) {
        const t = this.touches.get(id);
        if (t) t.moved = true;
    }

    onTouchEnded(id, pos, time) {
        const t = this.touches.get(id);
        if (!t) return;
        const dx = pos.x - t.start.x;
        const dy = pos.y - t.start.y;
        const dist = Math.hypot(dx, dy);
        const dt = time - t.time;

        if (dist < this.tapDistance && dt < this.tapThreshold) {
            this.emit('tap', { x: pos.x, y: pos.y });
        } else if (t.moved && dt > 0) {
            const velocity = dist / (dt / 1000);
            if (velocity > this.swipeVelocity) {
                this.emit('swipe', {
                    direction: Math.atan2(dy, dx),
                    velocity
                });
            }
        }
        this.touches.delete(id);
    }

    onTouchesMoved(touches) {
        if (touches.size === 2) {
            const [a, b] = [...touches.values()];
            const dist = Math.hypot(
                b.current.x - a.current.x,
                b.current.y - a.current.y
            );
            if (this.lastPinchDist) {
                const scale = dist / this.lastPinchDist;
                this.emit('pinch', { scale });
            }
            this.lastPinchDist = dist;
        }
    }
}

