import UIKit

class ThermalMonitor {
    func startMonitoring() {
        NotificationCenter.default.addObserver(
            self,
            selector: #selector(thermalStateChanged),
            name: ProcessInfo.thermalStateDidChangeNotification,
            object: nil
        )
    }

    @objc func thermalStateChanged() {
        switch ProcessInfo.processInfo.thermalState {
        case .nominal:
            setQualityLevel(.high)   // 60fps, max details
        case .fair:
            setQualityLevel(.medium) // 30fps, reduced effects
        case .serious:
            setQualityLevel(.low)    // 30fps, minimal effects
        case .critical:
            pauseGame()             // Show warning, save state
        }
    }

    func setQualityLevel(_ level: QualityLevel) {
        // Reduce shadow resolution, disable AA, lower draw distance
        QualitySettings.shadowResolution = level.shadowRes
        QualitySettings.antiAliasing = level.aa
        QualitySettings.lodBias = level.lodBias
    }
}

