    }

    void TrimMemory() {
        using (var playerClass = new AndroidJavaClass(
            "com.unity3d.player.UnityPlayer")) {
            var activity = playerClass
                .GetStatic<AndroidJavaObject>("currentActivity");
            activity.Call("trimMemory");
        }
    }
    #endif

    // Texture budget control
    public static Texture2D ScaleTexture(Texture2D source, 
        int maxSize) {
        if (source.width <= maxSize && 
            source.height <= maxSize)
            return source;
        float ratio = Mathf.Min(
            maxSize / (float)source.width,
            maxSize / (float)source.height);
        int newW = Mathf.RoundToInt(source.width * ratio);
        int newH = Mathf.RoundToInt(source.height * ratio);
        RenderTexture rt = RenderTexture.GetTemporary(
            newW, newH);
        Graphics.Blit(source, rt);
        Texture2D result = new Texture2D(newW, newH);
        RenderTexture.active = rt;
        result.ReadPixels(new Rect(0, 0, newW, newH), 0, 0);
        result.Apply();
        RenderTexture.active = null;
        RenderTexture.ReleaseTemporary(rt);
        return result;
    }
}

Adaptive Quality Scaling:
class QualityProfiler {
    static determineQuality(): QualityLevel {
        const mem = navigator.deviceMemory || 4;  // GB
        const cores = navigator.hardwareConcurrency || 4;
        const screenPixels = screen.width * screen.height;
        const gpu = this.detectGPU();

        let score = 0;
        if (mem >= 6) score += 30;
        else if (mem >= 4) score += 20;
        else if (mem >= 2) score += 10;

        if (cores >= 8) score += 20;
        else if (cores >= 4) score += 10;

        if (screenPixels < 500000) score += 20;  // low res
        else if (screenPixels < 2000000) score += 10;

        if (gpu?.includes('Adreno')) score += 15;
        else if (gpu?.includes('Mali')) score += 10;
        else if (gpu?.includes('Apple')) score += 15;

        if (score >= 70) return QualityLevel.High;
        if (score >= 40) return QualityLevel.Medium;
        return QualityLevel.Low;
    }

    static applyQuality(level: QualityLevel) {
        const config = {
            [QualityLevel.High]: {
                shadowRes: 2048,
                aaSamples: 4,
                lodBias: 2.0,
                maxParticles: 500,
                postProcess: true
            },
            [QualityLevel.Medium]: {
                shadowRes: 1024,
                aaSamples: 2,
                lodBias: 1.0,
                maxParticles: 200,
                postProcess: false
            },
            [QualityLevel.Low]: {
                shadowRes: 256,
                aaSamples: 0,
                lodBias: 0.5,
                maxParticles: 50,
                postProcess: false
            }
        };
        applySettings(config[level]);
    }
}

