            safeArea.y / Screen.height
        );
        Vector2 anchorMax = new Vector2(
            (safeArea.x + safeArea.width) / Screen.width,
            (safeArea.y + safeArea.height) / Screen.height
        );
        _panel.anchorMin = anchorMin;
        _panel.anchorMax = anchorMax;
    }
}

