const REFERENCE_WIDTH = 1080;
const REFERENCE_HEIGHT = 1920;

function scaleToScreen(value, axis = 'x') {
    const ref = axis === 'x' ? REFERENCE_WIDTH : REFERENCE_HEIGHT;
    const actual = axis === 'x' ? screen.width : screen.height;
    return (value / ref) * actual;
