function placeInZone(element, zone) {
    const rect = THUMB_ZONES[zone];
    const xMin = screen.width * rect.x[0];
    const xMax = screen.width * rect.x[1];
    const yMin = screen.height * rect.y[0];
    const yMax = screen.height * rect.y[1];
    element.style.left = xMin + 'px';
    element.style.width = (xMax - xMin) + 'px';
    element.style.top = yMin + 'px';
    element.style.height = (yMax - yMin) + 'px';
}

