        return Time.unscaledTime - lastInterstitial > INTERSTITIAL_COOLDOWN
            && interstitialCount < MAX_INTERSTITIAL;
    }

    public void ShowInterstitial() {
        if (!CanShowInterstitial()) return;
        string placement = "Interstitial_Ad";
        Advertisement.Load(placement, this);
        interstitialCount++;
        lastInterstitial = Time.unscaledTime;
