// Texture format detection and fallback
public static class TextureUtils {
    public static TextureFormat GetBestFormat() {
        #if UNITY_ANDROID
        // Check for ASTC support
        if (SystemInfo.SupportsTextureFormat(
            TextureFormat.ASTC_6x6)) {
            return TextureFormat.ASTC_6x6;
        }
        return TextureFormat.ETC2_RGBA;
        #elif UNITY_IOS
        // iOS devices support PVRTC or ASTC
        if (SystemInfo.SupportsTextureFormat(
            TextureFormat.ASTC_6x6)) {
            return TextureFormat.ASTC_6x6;
        }
        return TextureFormat.PVRTC_RGBA4;
        #else
        return TextureFormat.RGBA32;
        #endif
    }

    // Calculate memory usage of a texture
    public static long CalculateTextureMemory(
        int width, int height, TextureFormat format) {
        int bpp = format switch {
            TextureFormat.ASTC_6x6 => 6,     // bits per pixel
            TextureFormat.ETC2_RGBA => 8,
            TextureFormat.PVRTC_RGBA4 => 4,
            TextureFormat.RGBA32 => 32,
            _ => 32
        };
        return (width * height * bpp) / 8;  // bytes
    }

    // With mipmaps: multiply by ~1.33
    public static long WithMipmaps(long baseSize) {
        return (long)(baseSize * 1.33);
    }
}

