// Optimized mobile shader (Unity URP)
Shader "Mobile/OptimizedLit" {
    Properties {
        _MainTex ("Texture", 2D) = "white" {}
        _Color ("Color", Color) = (1,1,1,1)
        _Glossiness ("Smoothness", Range(0,1)) = 0.5
    }
    SubShader {
        Tags { "RenderType" = "Opaque" 
               "RenderPipeline" = "UniversalPipeline" }
        LOD 200

        Pass {
            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma target 3.0

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"

            struct Attributes {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
                float3 normalOS : NORMAL;
            };

            struct Varyings {
                float4 positionCS : SV_POSITION;
                float2 uv : TEXCOORD0;
                half3 worldNormal : TEXCOORD1;
                half3 worldPos : TEXCOORD2;
            };

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);
            half4 _Color;
            half _Glossiness;

            Varyings vert(Attributes input) {
                Varyings output;
                output.positionCS = TransformObjectToHClip(input.positionOS);
                output.uv = input.uv;
                output.worldNormal = TransformObjectToWorldNormal(input.normalOS);
                output.worldPos = TransformObjectToWorld(input.positionOS);
                return output;
            }

            half4 frag(Varyings input) : SV_Target {
                half4 texColor = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, input.uv);
                half3 albedo = texColor.rgb * _Color.rgb;

                // Single directional light
                Light mainLight = GetMainLight();
                half diffuse = max(0, dot(input.worldNormal, mainLight.direction));
                half3 lit = albedo * (mainLight.color * diffuse + unity_AmbientLight);

                // Simple specular
                half3 viewDir = normalize(_WorldSpaceCameraPos - input.worldPos);
                half3 halfVec = normalize(mainLight.direction + viewDir);
                half spec = pow(max(0, dot(input.worldNormal, halfVec)), _Glossiness * 128);
                lit += mainLight.color * spec * 0.3;

                return half4(lit, 1);
            }
            ENDHLSL
        }
    }
    FallBack "Mobile/Diffuse"
}

