// Persistent AR anchors with world maps
using UnityEngine.XR.ARFoundation;
using UnityEngine.XR.ARKit;
using System.IO;

public class ARWorldPersistence : MonoBehaviour {
    #if UNITY_IOS
    private ARWorldMapManager worldMapManager;

    void Start() {
        worldMapManager = GetComponent<ARWorldMapManager>();
    }

    public async void SaveWorldMap() {
        var session = UnityEngine.XR.ARFoundation.ARSession.GetSessionSubsystem<UnityEngine.XR.ARKit.ARKitSessionSubsystem>();

        if (session == null) return;

        session.GetCurrentWorldMapAsync((worldMap) => {
            if (worldMap.Status == ARWorldMapStatus.Success) {
                byte[] data = worldMap.Serialize();
                string path = Path.Combine(
                    Application.persistentDataPath,
                    "world_map.data");
                File.WriteAllBytes(path, data);
                Debug.Log($"World map saved: {data.Length} bytes");
            }
        });
    }

    public async void LoadWorldMap() {
        string path = Path.Combine(
            Application.persistentDataPath,
            "world_map.data");
        if (!File.Exists(path)) return;

        byte[] data = File.ReadAllBytes(path);
        var session = ARSession.GetSessionSubsystem<ARKitSessionSubsystem>();

        var worldMap = ARWorldMap.Deserialize(data);
        session.ApplyWorldMap(worldMap);
        Debug.Log("World map restored with anchors");
    }
    #endif

    // Cross-platform anchor persistence
    public void SaveAnchorPosition(string id, Vector3 position, 
        Quaternion rotation) {
        var data = new ARAnchorData {
            id = id,
            posX = position.x,
            posY = position.y,
            posZ = position.z,
            rotX = rotation.x,
            rotY = rotation.y,
            rotZ = rotation.z,
            rotW = rotation.w
        };
        string json = JsonUtility.ToJson(data);
        PlayerPrefs.SetString("ar_anchor_" + id, json);
