// CoreML integration (Swift)
import CoreML
import Vision

class ImageClassifier {
    private let model: VNCoreMLModel

    init?() {
        guard let mlModel = try? MobileNetV2(configuration: MLModelConfiguration()).model,
              let visionModel = try? VNCoreMLModel(for: mlModel) else {
            return nil
        }
        self.model = visionModel
    }

    func classify(_ image: CIImage) async throws -> String {
        let request = VNCoreMLRequest(model: model)
        request.imageCropAndScaleOption = .centerCrop

        let handler = VNImageRequestHandler(ciImage: image)
        try handler.perform([request])

        guard let results = request.results as? [VNClassificationObservation],
              let best = results.first else {
            throw MLModelError.unknown
        }

        return "\(best.identifier) (\(Int(best.confidence * 100))%)"
    }
}

